class Solution {
    public int meetRequirement(int n, int[][] lights, int[] requirement) {
        int[] diff = new int[n + 1];
        for (int[] l : lights) {
            diff[Math.max(0, l[0] - l[1])]++;
            diff[Math.min(n, l[0] + l[1] + 1)]--;
        }
        int cur = 0, ans = 0;
        for (int i = 0; i < n; i++) {
            cur += diff[i];
            if (cur >= requirement[i]) ans++;
        }
        return ans;
    }
}
